/**
 * SPEC-055-iter-2 · AC-01/AC-06 — badges de permiso ternarios.
 * Semántica: granted → chip verde «Concedido»; not-determined/unknown/snapshot
 * null → chip ámbar «Pendiente» (trigger de tooltip con el siguiente paso);
 * denied/restricted → chip rojo «No concedido». Localización por data-testid
 * (permission-badge-microphone / permission-badge-system) y data-state
 * (granted|pending|denied), garantizados por la spec. El tooltip real al hover
 * es verificación MANUAL (jsdom + Radix grace area, lección SPEC-001); aquí se
 * aserta el estado y el nombre accesible.
 * Generated by QA Dev agent.
 */
import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { PermissionBadges } from '@/components/recording/PermissionBadges'
import { TooltipProvider } from '@/components/ui/tooltip'
import type { PermissionsSnapshot } from '@/types/audio'

function renderBadges(permissions: PermissionsSnapshot | null): ReturnType<typeof render> {
  return render(
    <TooltipProvider>
      <PermissionBadges permissions={permissions} />
    </TooltipProvider>
  )
}

describe('PermissionBadges', () => {
  // SPEC-055-iter-2 · AC-06
  it('renders green "Concedido" chips for both badges when everything is granted', () => {
    renderBadges({ microphone: 'granted', systemAudio: 'granted' })

    expect(screen.getByTestId('permission-badge-microphone')).toHaveAttribute(
      'data-state',
      'granted'
    )
    expect(screen.getByTestId('permission-badge-system')).toHaveAttribute('data-state', 'granted')
    expect(screen.getAllByText('Concedido')).toHaveLength(2)
  })

  // SPEC-055-iter-2 · AC-01
  it('renders amber "Pendiente" chips when permissions are not determined yet', () => {
    renderBadges({ microphone: 'not-determined', systemAudio: 'not-determined' })

    expect(screen.getByTestId('permission-badge-microphone')).toHaveAttribute(
      'data-state',
      'pending'
    )
    expect(screen.getByTestId('permission-badge-system')).toHaveAttribute('data-state', 'pending')
    expect(screen.getAllByText('Pendiente')).toHaveLength(2)
    expect(screen.queryByText('No concedido')).not.toBeInTheDocument()
  })

  // SPEC-055-iter-2 · AC-01 (snapshot null = pendiente, decisión asumida)
  it('renders pending chips while the permissions snapshot is still null', () => {
    renderBadges(null)

    expect(screen.getByTestId('permission-badge-microphone')).toHaveAttribute(
      'data-state',
      'pending'
    )
    expect(screen.getByTestId('permission-badge-system')).toHaveAttribute('data-state', 'pending')
  })

  // SPEC-055-iter-2 · AC-03 (estado mixto: cada badge con su semáforo)
  it('renders a red "No concedido" chip only for the denied permission in mixed states', () => {
    renderBadges({ microphone: 'denied', systemAudio: 'granted' })

    expect(screen.getByTestId('permission-badge-microphone')).toHaveAttribute(
      'data-state',
      'denied'
    )
    expect(screen.getByTestId('permission-badge-system')).toHaveAttribute('data-state', 'granted')
    expect(screen.getByText('No concedido')).toBeInTheDocument()
    expect(screen.getByText('Concedido')).toBeInTheDocument()
  })
})
